```lean
Trivialization.prod_apply.{u_1, u_2, u_3, u_4, u_5, u_6} (𝕜 : Type u_1) {B : Type u_2} [NontriviallyNormedField 𝕜]
  [TopologicalSpace B] {F₁ : Type u_3} [NormedAddCommGroup F₁] [NormedSpace 𝕜 F₁] {E₁ : B → Type u_4}
  [TopologicalSpace (TotalSpace F₁ E₁)] {F₂ : Type u_5} [NormedAddCommGroup F₂] [NormedSpace 𝕜 F₂] {E₂ : B → Type u_6}
  [TopologicalSpace (TotalSpace F₂ E₂)] [(x : B) → AddCommMonoid (E₁ x)] [(x : B) → Module 𝕜 (E₁ x)]
  [(x : B) → AddCommMonoid (E₂ x)] [(x : B) → Module 𝕜 (E₂ x)] {e₁ : Trivialization F₁ TotalSpace.proj}
  {e₂ : Trivialization F₂ TotalSpace.proj} [(x : B) → TopologicalSpace (E₁ x)] [(x : B) → TopologicalSpace (E₂ x)]
  [FiberBundle F₁ E₁] [FiberBundle F₂ E₂] [Trivialization.IsLinear 𝕜 e₁] [Trivialization.IsLinear 𝕜 e₂] {x : B}
  (hx₁ : x ∈ e₁.baseSet) (hx₂ : x ∈ e₂.baseSet) (v₁ : E₁ x) (v₂ : E₂ x) :
  ↑(e₁.prod e₂) { proj := x, snd := (v₁, v₂) } =
    (x, (continuousLinearEquivAt 𝕜 e₁ x hx₁) v₁, (continuousLinearEquivAt 𝕜 e₂ x hx₂) v₂)
```

